const GENERATED_NOTICE =
  "<!-- Do not edit this file. It is automatically generated by API Documenter. -->";

/**
 * Merges API Documenter's per-symbol pages into one Markdown file per package.
 *
 * Pages named `<package>.<path>.md` are appended, in hierarchical order, to
 * `<package>.md`. Each section keeps an HTML anchor named after its original
 * page so links resolve within the bundle (`#pkg.symbol`) or across bundles
 * (`./other.md#other.symbol`). `index.md` becomes `README.md`.
 *
 * @param pages - Generated page contents keyed by filename.
 * @returns Bundled Markdown keyed by filename.
 */
export function bundlePages(pages) {
  const sections = new Map();
  for (const name of Object.keys(pages).sort(comparePageNames)) {
    if (!name.endsWith(".md") || name === "README.md") continue;
    const target = name === "index.md" ? "README.md" : `${packageOf(name)}.md`;
    if (!sections.has(target)) sections.set(target, []);
    sections.get(target).push(renderSection(name, pages[name]));
  }
  return Object.fromEntries(
    [...sections].map(([name, parts]) => [
      name,
      `${[GENERATED_NOTICE, ...parts].join("\n\n")}\n`,
    ]),
  );
}

function packageOf(name) {
  return name.slice(0, name.indexOf("."));
}

// Parents precede their members: `a`, `a.foo`, `a.foo.bar`, `a.fop`.
function comparePageNames(a, b) {
  const sa = a.slice(0, -".md".length).split(".");
  const sb = b.slice(0, -".md".length).split(".");
  for (let i = 0; i < Math.min(sa.length, sb.length); i++)
    if (sa[i] !== sb[i]) return sa[i] < sb[i] ? -1 : 1;
  return sa.length - sb.length;
}

function renderSection(name, contents) {
  const id = name.slice(0, -".md".length);
  const body = contents
    .split("\n")
    .filter((line) => line !== GENERATED_NOTICE && !line.startsWith("[Home]("))
    .join("\n")
    .replace(
      /\]\(\.\/([^)#\s]+)\.md\)/g,
      (_, target) => `](${linkTo(id, target)})`,
    )
    .trim();
  return `<a name="${id}"></a>\n\n${body}`;
}

function linkTo(from, target) {
  if (target === "index") return "./README.md";
  const pkg = packageOf(`${target}.`);
  if (target === pkg)
    return from.startsWith(`${pkg}.`) ? `#${pkg}` : `./${pkg}.md`;
  return packageOf(`${from}.`) === pkg ? `#${target}` : `./${pkg}.md#${target}`;
}
